            n: gs.length,
            pct: Math.round(score / w * 100)
          };
        }).sort((a, b) => b.pct - a.pct);
      });
    }
    ngOnInit() {
      this.load();
      if (this.mine) this.hr.me().subscribe({
        next: e => this.me.set(e),
        error: () => {}
      });else if (this.viewAll || this.canManage) this.hr.employees().subscribe({
        next: l => this.emps.set(l),
        error: () => {}
      });
    }
    load() {
      this.hr.records('goal').subscribe({
        next: l => this.allGoals.set(l),
        error: e => this.flash(errMsg(e, this.i18n), true)
      });
      this.hr.records('review').subscribe({
        next: l => this.allReviews.set(l),
        error: () => {}
      });
    }
    name(e) {
      return empName(e, this.i18n);
    }
    empLabel(no) {
      const e = this.emps().find(x => x.empNo === no);
      return e ? this.name(e) : no ?? '';
